class.description:
A [PerformanceSummary] is returned by [method PerformanceRecorder.get_summary]. It holds one [PerformanceColumnSummary] per recorded column, the number of frames and rows, the duration, and the hitches (frames slower than [member PerformanceRecordingProfile.hitch_threshold_usec]). Check it against a [PerformanceBudget] with [method PerformanceBudget.check_summary], or write it with [method to_text].
[codeblocks]
[gdscript]
var summary = PerformanceRecorder.get_summary()
print("%d frames, %d hitches" % [summary.get_frame_count(), summary.get_hitch_count()])
for column in summary.get_columns():
	print("%s: mean %.1f, p99 %.1f" % [column.get_name(), column.get_mean(), column.get_p99()])
[/gdscript]
[csharp]
var summary = PerformanceRecorder.GetSummary();
GD.Print($"{summary.GetFrameCount()} frames, {summary.GetHitchCount()} hitches");
foreach (var column in summary.GetColumns())
{
	GD.Print($"{column.GetName()}: mean {column.GetMean():F1}, p99 {column.GetP99():F1}");
}
[/csharp]
[/codeblocks]
